import{_ as i,o as t,c as e,ag as n}from"./chunks/framework.CxkNbRKf.js";const c=JSON.parse('{"title":"Database migration","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/database-migration.md","filePath":"admin-guide/web-ui/database-migration.md","lastUpdated":1786379412000}'),s={name:"admin-guide/web-ui/database-migration.md"};function r(o,a,l,d,g,m){return t(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="database-migration" tabindex="-1">Database migration <a class="header-anchor" href="#database-migration" aria-label="Permalink to &quot;Database migration&quot;">​</a></h1><p>The database migration tool lets administrators apply database schema upgrades through the admin interface without requiring command-line access. It is used when upgrading NADA to a new version.</p><div class="warning custom-block"><p class="custom-block-title">Back up your database before running migrations</p><p>Always take a full database backup before applying any migration. Migrations modify the schema and data and cannot be automatically reversed.</p></div><h2 id="accessing-database-migration" tabindex="-1">Accessing database migration <a class="header-anchor" href="#accessing-database-migration" aria-label="Permalink to &quot;Accessing database migration&quot;">​</a></h2><p>Go to <strong>Settings → Database migration</strong> in the administrator menu.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Database migration page showing current version and list of pending/applied migrations</em></p></div><h2 id="understanding-the-migration-list" tabindex="-1">Understanding the migration list <a class="header-anchor" href="#understanding-the-migration-list" aria-label="Permalink to &quot;Understanding the migration list&quot;">​</a></h2><p>The page shows:</p><ul><li><strong>Current version</strong> — the migration watermark currently applied to the database</li><li><strong>Available migrations</strong> — all migration files with their status:</li></ul><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Pending</td><td>Not yet applied</td></tr><tr><td>Current</td><td>The most recently applied migration</td></tr><tr><td>Applied</td><td>Previously applied</td></tr></tbody></table><h2 id="running-migrations" tabindex="-1">Running migrations <a class="header-anchor" href="#running-migrations" aria-label="Permalink to &quot;Running migrations&quot;">​</a></h2><h3 id="run-all-pending-migrations" tabindex="-1">Run all pending migrations <a class="header-anchor" href="#run-all-pending-migrations" aria-label="Permalink to &quot;Run all pending migrations&quot;">​</a></h3><p>Click <strong>Run latest</strong> to apply all pending migrations in sequence. This is the standard step when upgrading NADA.</p><h3 id="run-a-specific-migration" tabindex="-1">Run a specific migration <a class="header-anchor" href="#run-a-specific-migration" aria-label="Permalink to &quot;Run a specific migration&quot;">​</a></h3><p>Click <strong>Run</strong> next to an individual migration to apply it in isolation.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Migration list with Run and Run latest buttons</em></p></div><h2 id="marking-migrations-manually" tabindex="-1">Marking migrations manually <a class="header-anchor" href="#marking-migrations-manually" aria-label="Permalink to &quot;Marking migrations manually&quot;">​</a></h2><p>If you have applied a migration manually (for example, via a database administration tool), record it without re-running it by clicking <strong>Mark as applied</strong>. That sets the watermark through the selected migration and all earlier ones—it does <strong>not</strong> execute migration code. Use <strong>Unmark</strong> on an applied migration to lower the watermark to the previous migration so that migration and all later ones show as pending again (schema and data are unchanged).</p><div class="warning custom-block"><p class="custom-block-title">Re-running migrations</p><p>Unmarking is for recovery only. Re-running migrations can fail with duplicate column errors or duplicate data unless the migration was written to be idempotent. Back up the database first.</p></div><h2 id="command-line" tabindex="-1">Command line <a class="header-anchor" href="#command-line" aria-label="Permalink to &quot;Command line&quot;">​</a></h2><p>The same migration runner is available from the NADA root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span></span></code></pre></div><p>For inspecting versions, marking migrations after manual SQL, recovering from failed runs, and other CLI-only workflows, see <a href="/nada-documentation/installation-guide/database-migrations-cli.html">Database migrations (CLI)</a>.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Database debug mode is automatically disabled during a migration run.</li><li>Migration files are identified by a 14-digit timestamp prefix (e.g., <code>20260705120001</code>).</li><li>Always read the NADA release notes for any special instructions before running migrations.</li></ul>',25)])])}const p=i(s,[["render",r]]);export{c as __pageData,p as default};
